import java.util.Scanner;
public class JStars2
{
	public static void main (String[] args)
	{		
		//Khatwa 1: Qira'at adad as-sufuf fi namat muthallath an-nujoom al-maqlub
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil adad as-sufuf fi namat muthallath an-nujoom al-maqlub: ");
		int N = scan.nextInt();
		scan.close();
		//Khatwa 2: Tibaa'at as-sufuf fi namat an-nujoom, wahidan bi wahid
		for (int i = 1; i <= N; i++)
		{
			//Khatwa 2.1: Tibaa'at al-nujoom fi as-saff al-i
			for (int j = 1; j <= N-i+1; j++) {
				System.out.print ("*");
			}
			System.out.println();
		}
	}
}
